import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-thumbnail-card';

  const pos = config.scenePlacement?.position ?? [-2.5, -0.2, 0];
  const rot = config.scenePlacement?.rotation ?? [0, 0, 0];
  const scl = config.scenePlacement?.scale ?? [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  const baseY = group.position.y;

  // accent edge frame (shown on focus)
  const frameGeo = new THREE.RingGeometry(0.9, 0.94, 4, 1);
  const frameMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(0xff2a38),
    transparent: true,
    opacity: 0,
    side: THREE.DoubleSide,
  });
  const accentFrame = new THREE.Mesh(frameGeo, frameMat);
  accentFrame.rotation.x = Math.PI / 2;
  accentFrame.position.y = 0.01;
  group.add(accentFrame);

  let meshRoot = null;
  let mixer = null;
  let disposed = false;

  const meshUrl = config.assets?.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.load(meshUrl, (gltf) => {
      if (disposed) return;
      meshRoot = gltf.scene || gltf.scenes?.[0];
      if (meshRoot) {
        group.add(meshRoot);
      }
    });
  }

  // caption strip (simple plane, no text content specified)
  const stripGeo = new THREE.PlaneGeometry(1.6, 0.35);
  const stripMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(0x16161d),
    roughness: 0.55,
    metalness: 0.4,
  });
  const captionStrip = new THREE.Mesh(stripGeo, stripMat);
  captionStrip.position.set(0, -0.9, 0.02);
  group.add(captionStrip);

  let hoverTween = null;
  let pressTween = null;

  const onHoverIn = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(frameMat, { opacity: 0.9, duration: 0.3 });
  };

  const onHoverOut = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(frameMat, { opacity: 0, duration: 0.3 });
  };

  const onClick = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, {
        x: scl[0] * 0.97,
        y: scl[1] * 0.97,
        z: scl[2] * 0.97,
        duration: 0.12,
        ease: 'back.out',
      })
      .to(group.scale, {
        x: scl[0],
        y: scl[1],
        z: scl[2],
        duration: 0.12,
        ease: 'back.out',
      });

    if (group.userData.emit) {
      group.userData.emit('hub-home.select', { nodeId: config.id });
    }
  };

  const onFocus = () => {
    gsap.to(frameMat, { opacity: 0.9, duration: 0.2 });
  };

  const onBlur = () => {
    gsap.to(frameMat, { opacity: 0, duration: 0.2 });
  };

  group.userData.handlers = {
    hover: onHoverIn,
    hoverIn: onHoverIn,
    hoverOut: onHoverOut,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
  };

  group.userData.cleanup = () => {
    disposed = true;
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(frameMat);

    frameGeo.dispose();
    frameMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();

    if (meshRoot) {
      meshRoot.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => {
            Object.keys(m).forEach((key) => {
              const val = m[key];
              if (val && val.isTexture) val.dispose();
            });
            m.dispose();
          });
        }
      });
    }
  };

  return group;
}
